                                                                                                                       \
    arm_cmsis_nn_status FUNC_NAME(const cmsis_nn_context *ctx,                                                         \
                                  const PARAMS_T *params,                                                              \
                                  const cmsis_nn_dims *input_dims,                                                     \
                                  const SCALAR_T *input,                                                               \
                                  const cmsis_nn_dims *output_dims,                                                    \
