        {                                                                                                              \
            size_t elems = (size_t)in_dims[0];                                                                         \
            FUNC_NAME##_copy_elems(input, output, elems);                                                              \
            return ARM_CMSIS_NN_SUCCESS;                                                                               \
        }                                                                                                              \
                                                                                                                       \
