    int32_t remainder = remainder_mask & dividend;

    result = dividend >> exponent;

    int32_t threshold = remainder_mask >> 1;
    if (result < 0)
    {
        threshold++;
    }
    if (remainder > threshold)
    {
        result++;
    }

    return result;

}

