                                              const cmsis_nn_dims *input_dims,
                                              const cmsis_nn_dims *filter_dims)
{
    return (input_dims->h == 1) && (conv_params->dilation.w == 1) && (filter_dims->h == 1) &&
        ((conv_params->stride.w * input_dims->c) % 4 == 0) && (input_dims->c == filter_dims->c);
}

